SR63.ministryLogoWordBase64='';
SR63.teacherWordKit=function(meta,{landscape=false,maroon='920D39'}={}){
 const esc=x=>String(x??'').replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
 const width=landscape?15010:10030,pgWidth=landscape?16838:11906;
 const r=(x,{bold=false,size=18,color='172D3C'}={})=>`<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial" w:eastAsia="Arial"/><w:rtl/><w:lang w:bidi="ar-QA"/>${bold?'<w:b/><w:bCs/>':''}<w:sz w:val="${size}"/><w:szCs w:val="${size}"/><w:color w:val="${color}"/></w:rPr>${String(x??'').split(/\r?\n/).map((line,i)=>(i?'<w:br/>':'')+`<w:t xml:space="preserve">${esc(line)}</w:t>`).join('')}</w:r>`;
 const p=(value,{size=18,bold=false,color='172D3C',center=false,after=70,keep=false}={})=>`<w:p><w:pPr><w:bidi/><w:jc w:val="${center?'center':'right'}"/><w:spacing w:before="0" w:after="${after}" w:line="260" w:lineRule="auto"/>${keep?'<w:keepNext/>':''}</w:pPr>${r(value,{size,bold,color})}</w:p>`;
 const heading=(x,opts={})=>p(x,{size:24,bold:true,color:maroon,after:95,keep:true,...opts});
 const borders='<w:tblBorders><w:top w:val="single" w:sz="6" w:color="9EA9B5"/><w:left w:val="single" w:sz="6" w:color="9EA9B5"/><w:bottom w:val="single" w:sz="6" w:color="9EA9B5"/><w:right w:val="single" w:sz="6" w:color="9EA9B5"/><w:insideH w:val="single" w:sz="5" w:color="B5C0C8"/><w:insideV w:val="single" w:sz="5" w:color="B5C0C8"/></w:tblBorders>';
 const gridTable=(rows,widths,{head=true,size=17,alternate=false,tableWidth=width,compact=false}={})=>{
  if(!rows?.length)return '';
  const div=widths.reduce((a,b)=>a+b,0),sizes=widths.map(w=>Math.round(w/div*tableWidth));sizes[sizes.length-1]+=tableWidth-sizes.reduce((a,b)=>a+b,0);
  const rowXml=rows.map((cells,i)=>{
   let col=0;
   const cellXml=cells.map(v=>{
    const o=(v&&typeof v==='object'&&!Array.isArray(v))?v:{text:v};
    const span=Math.max(1,Number(o.span)||1),w=sizes.slice(col,col+span).reduce((a,b)=>a+b,0);col+=span;
    const shade=o.shade||(head&&i===0?maroon:(alternate&&i%2===0?'F1F5F6':null));
    const props=`<w:tcPr><w:tcW w:w="${w}" w:type="dxa"/>${span>1?`<w:gridSpan w:val="${span}"/>`:''}${shade?`<w:shd w:fill="${shade}"/>`:''}<w:vAlign w:val="${o.middle?'center':'top'}"/></w:tcPr>`;
    const content=o.xml?(o.prefix?p(o.prefix,{size:o.size||size,bold:!!o.bold,after:25}):'')+o.xml+'<w:p/>':p(o.text??'',{size:o.size||size,bold:o.bold===undefined?(head&&i===0):o.bold,color:o.color||(shade===maroon?'FFFFFF':'172D3C'),center:!!o.center,after:compact?8:28});
    return `<w:tc>${props}${content}</w:tc>`;
   }).join('');
   if(col!==sizes.length)throw Error(`عدد أعمدة Word غير متطابق: ${col} / ${sizes.length}`);
   return `<w:tr><w:trPr>${head&&i===0?'<w:tblHeader/>':''}${cells.some(c=>c?.noSplit)?'<w:cantSplit/>':''}</w:trPr>${cellXml}</w:tr>`;
  }).join('');
  return `<w:tbl><w:tblPr><w:tblW w:w="${tableWidth}" w:type="dxa"/><w:tblLayout w:type="fixed"/><w:bidiVisual/>${borders}<w:tblCellMar><w:top w:w="${compact?48:80}" w:type="dxa"/><w:bottom w:w="${compact?48:80}" w:type="dxa"/><w:start w:w="75" w:type="dxa"/><w:end w:w="75" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>${sizes.map(w=>`<w:gridCol w:w="${w}"/>`).join('')}</w:tblGrid>${rowXml}</w:tbl>`;
 };
 const table=(rows,widths,opts={})=>gridTable(rows,widths,opts);
 const sign=gridTable([
  ['جهة الاعتماد','الاسم','التوقيع','التاريخ'],
  ['المعلم',meta.teacher||'—','........................','................'],
  ['منسق المادة',meta.coordinator||'........................','........................','................'],
  ['النائب الأكاديمي',meta.vice||'........................','........................','................'],
  ['مدير المدرسة',meta.principal||'........................','........................','................']
 ],[2200,4200,2400,1300],{size:15,compact:true,alternate:true});
 const drawing=`<w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="4050000" cy="890000"/><wp:docPr id="1" name="الشعار الرسمي لوزارة التربية والتعليم والتعليم العالي"/><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic><pic:nvPicPr><pic:cNvPr id="0" name="ministry.png"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="rId1"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="4050000" cy="890000"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing>`;
 const hdrXml=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:hdr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><w:p><w:pPr><w:bidi/><w:jc w:val="left"/><w:spacing w:after="80"/></w:pPr><w:r>${drawing}</w:r></w:p></w:hdr>`;
 const xml=(tag,body)=>`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><${tag} xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">${body}</${tag}>`;
 const make=(body,name,overrides={})=>{
  const sect=`<w:sectPr><w:headerReference w:type="default" r:id="rId2"/><w:footerReference w:type="default" r:id="rId3"/><w:pgSz w:w="${pgWidth}" w:h="${landscape?11906:16838}" ${landscape?'w:orient="landscape"':''}/><w:pgMar w:top="1300" w:right="910" w:bottom="960" w:left="910" w:header="240" w:footer="430"/></w:sectPr>`;
  const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let acc=0,bits=0;const buf=[];for(const ch of SR63.ministryLogoWordBase64){if(ch==='=')break;const n=alphabet.indexOf(ch);if(n<0)continue;acc=(acc<<6)|n;bits+=6;if(bits>=8){bits-=8;buf.push((acc>>>bits)&255);}}
  const base=new Uint8Array(buf);
  const files={
   '[Content_Types].xml':'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/><Override PartName="/word/header1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml"/><Override PartName="/word/footer1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml"/></Types>',
   '_rels/.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>',
   'word/_rels/document.xml.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/header" Target="header1.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" Target="footer1.xml"/></Relationships>',
   'word/_rels/header1.xml.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/ministry.png"/></Relationships>',
   'word/media/ministry.png':base,
   'word/styles.xml':xml('w:styles','<w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:rtl/><w:lang w:bidi="ar-QA"/><w:sz w:val="18"/><w:szCs w:val="18"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:bidi/><w:jc w:val="right"/></w:pPr></w:pPrDefault></w:docDefaults>'),
   'word/document.xml':'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><w:body>'+body+sect+'</w:body></w:document>',
   'word/header1.xml':hdrXml,
   'word/footer1.xml':xml('w:ftr',p(`${meta.schoolName||'المدرسة'} — وثيقة تربوية للمراجعة والاعتماد`,{size:14,center:true,color:'666E77'}))
  };
  Object.assign(files,overrides);
  const encoder=new TextEncoder(),crcTable=new Uint32Array(256),parts=[],central=[];
  for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;crcTable[n]=c>>>0;}
  const crc32=a=>{let c=0xffffffff;for(const b of a)c=(crcTable[(c^b)&255]^(c>>>8))>>>0;return(c^0xffffffff)>>>0;};
  const record=(size,items)=>{const b=new Uint8Array(size),view=new DataView(b.buffer);for(const [at,bytes,value] of items){if(bytes===2)view.setUint16(at,value,true);else view.setUint32(at,value>>>0,true);}return b;};
  let offset=0;
  for(const [path,content] of Object.entries(files)){
   const filename=encoder.encode(path),data=content instanceof Uint8Array?content:encoder.encode(content),checksum=crc32(data);
   const local=record(30,[[0,4,0x04034b50],[4,2,20],[12,2,0x21],[14,4,checksum],[18,4,data.length],[22,4,data.length],[26,2,filename.length]]);
   parts.push(local,filename,data);
   const dir=record(46,[[0,4,0x02014b50],[4,2,20],[6,2,20],[14,2,0x21],[16,4,checksum],[20,4,data.length],[24,4,data.length],[28,2,filename.length],[42,4,offset]]);
   central.push(dir,filename);offset+=local.length+filename.length+data.length;
  }
  const centralSize=central.reduce((n,x)=>n+x.length,0),end=record(22,[[0,4,0x06054b50],[8,2,Object.keys(files).length],[10,2,Object.keys(files).length],[12,4,centralSize],[16,4,offset]]);
  const out=new Uint8Array(offset+centralSize+end.length);let cursor=0;
  for(const part of [...parts,...central,end]){out.set(part,cursor);cursor+=part.length;}
  return {bytes:out,filename:name.replace(/[\\/:*?"<>|]/g,'-').slice(0,155)+'.docx'};
 };
 return {p,heading,header:heading,table,gridTable,sign,make,esc,width};
};
SR63.teacherWordDownload=function(output){
 const blob=new Blob([output.bytes],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=output.filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);return output.filename;
};
SR63.teacherImprovementWordBuild=function(analysis,edits={}){
 if(analysis.groups.length!==1)throw Error('خطة تحسين الأداء تُصدَّر لشعبة واحدة فقط. اختر الشعبة أولًا.');
 const kit=SR63.teacherWordKit({schoolName:analysis.schoolName,teacher:analysis.teacher,coordinator:analysis.coordinator,vice:analysis.academicViceName,principal:analysis.principalName},{landscape:true});
 const {p,heading,gridTable,sign,make,width}=kit;
 const pct=x=>typeof x==='number'?x.toFixed(1)+'%':'—';
 const diff=x=>typeof x==='number'?(x>0?'+':'')+x.toFixed(1)+' نقطة':'—';
 const preset=SR63.teacherImprovementDefaults(analysis.subject),edit={...preset,...edits};
 const klass=analysis.groups[0]?.className||'—';
 const labels={low:'الطلبة ذوو الأداء المتدني',middle:'الطلبة ذوو الأداء المتوسط',high:'الطلبة ذوو الأداء المرتفع'};
 const line=(key)=>{
  const students=analysis.bands[key]||[],measured=students.filter(s=>s.current!==null&&s.previous!==null);
  const succeed=measured.filter(s=>key==='low'?s.change>=5:key==='middle'?s.change>=3:(s.previous>=analysis.upper&&s.current>=analysis.upper)).length;
  const actual=measured.length?`${succeed} من ${measured.length} طالبًا — ${(succeed/measured.length*100).toFixed(1)}%`:'غير قابل للقياس حتى تتوافر نتيجتان';
  const list=students.length?students.map((s,i)=>[
   {text:s.studentName,size:15,bold:i%2===0},
   {text:s.className,size:15,center:true},
   {text:typeof s.score==='number'?`${s.score}/${s.total}`:'—',size:15,center:true},
   {text:pct(s.current),size:15,center:true},
   {text:pct(s.previous),size:15,center:true},
   {text:diff(s.change),size:14,center:true}
  ]):[[{text:'لا يوجد طلاب في هذا المستوى',span:6,size:16}]];
  const nested=gridTable([['اسم الطالب','الصف','الدرجة','الحالي','السابق','التغير'],...list],[4350,950,1100,950,950,1350],{tableWidth:Math.round(width*(4150/11000))-220,head:true,size:14,compact:true,alternate:true});
  const mean=students.filter(s=>s.current!==null),avg=mean.length?(mean.reduce((sum,s)=>sum+s.current,0)/mean.length).toFixed(1)+'%':'—';
  return [
   {text:`${labels[key]}\n(${students.length} طلاب)`,bold:true,size:18,shade:'E4EDF2',noSplit:students.length<=8},
   {xml:nested,prefix:`متوسط مستوى الفئة: ${avg} — العدد: ${students.length}`,size:15},
   {text:edit[key+'Goal']||'—',size:17},
   {text:edit[key+'Actions']||'—',size:16},
   {text:`المستهدف: ${edit[key+'Indicator']||'—'}\n\nنسبة تحقق المؤشر: ${actual}`,size:16,bold:false,shade:'F5F8FA'}
  ];
 };
 let body=p('خطة تحسين أداء الطلبة',{size:32,bold:true,color:'920D39',center:true,after:95});
 body+=gridTable([
  [{text:'اسم المعلم',bold:true,shade:'DCE8F0'},{text:analysis.teacher}],
  [{text:'المادة الدراسية',bold:true,shade:'DCE8F0'},{text:analysis.subjectLabel}],
  [{text:'المرحلة / الصف / الشعبة',bold:true,shade:'DCE8F0'},{text:klass}],
  [{text:'اسم المدرسة / العام الأكاديمي',bold:true,shade:'DCE8F0'},{text:`${analysis.schoolName} — ${analysis.academicYear}`}],
  [{text:'التقييم الحالي / السابق',bold:true,shade:'DCE8F0'},{text:`${analysis.examName} / ${analysis.prevExamName||'لا يوجد'}`}]
 ],[2900,7100],{head:false,size:17,compact:true});
 body+=p(`تحليل بيانات نتائج الطلبة وخطة تحسين أدائهم — ${klass} — إجمالي الطلاب: ${analysis.studentCount}`,{size:23,bold:true,color:'920D39',center:true,after:95});
 body+=gridTable([
  [{text:'تحليل بيانات نتائج الطلبة وخطة تحسين أدائهم',span:5,bold:true,size:22,center:true,shade:'DCE8F0'}],
  ['الطلبة','البيانات الكمية الأساسية لمستوى الطلبة','الأهداف المنشودة','خطة التحسين (آلية التدخل والدعم التي ستساعد على تحقيق الأهداف)','المخرجات المتوقعة (بيانات كمية قابلة للقياس)'].map(text=>({text,bold:true,shade:'920D39',color:'FFFFFF',size:18})),
  line('low'),line('middle'),line('high')
 ],[1350,4150,1750,1900,1850],{size:17,head:false,alternate:false});
 if(analysis.bands.missing.length){
  body+=heading(`حالات يلزم استكمال رصدها — ${analysis.bands.missing.length} طالبًا`);
  const statuses={absent:'غائب',excused:'غياب بعذر',unexcused:'غياب دون عذر',deprived:'محروم',not_enrolled:'غير مقيد',unentered:'غير مرصود'};
  body+=p('لا تُحتسب هذه الحالات ضمن مستويات الأداء ولا تتحول إلى درجة صفر.',{size:16});
  body+=gridTable([['اسم الطالب','الشعبة','الحالة'],...analysis.bands.missing.map(s=>[s.studentName,s.className,statuses[s.currentStatus]||'غير محتسب'])],[5400,2000,2500],{size:17,alternate:true,compact:true});
 }
 body+=heading('المراجعة والمتابعة');
 body+=p('تُراجع الأهداف والإجراءات بعد إعلان نتيجة الاختبار التالي، وتقارن درجات الطلاب في الاختبارين على أساس النسب المئوية للدرجات المرصودة، وتُوثق نتائج التدخل ومؤشرات تحقق الأهداف.',{size:17,after:90});
 body+=heading('اعتماد خطة التحسين');body+=sign;
 return make(body,`خطة-تحسين-أداء-الطلبة-${analysis.subjectLabel}-${klass}-${analysis.examName}`);
};
SR63.teacherQuantitativeWordBuild=function(analysis,edits={}){
 const kit=SR63.teacherWordKit({schoolName:analysis.schoolName,teacher:analysis.teacher,coordinator:analysis.coordinator,vice:analysis.academicViceName,principal:analysis.principalName},{landscape:false});
 const {p,heading,gridTable,sign,make}=kit;
 const fmt=x=>x===null||x===undefined?'—':Number(x).toFixed(1)+'%';
 const change=x=>x===null||x===undefined?'—':(x>0?'+':'')+Number(x).toFixed(1)+' نقطة';
 const targets={success:90,achievement:75,valueAdded:3,high90:30,...(edits.targets||{})};
 const achieved=(v,t)=>v===null||v===undefined?'لا تتوافر بيانات':Number(v)>=Number(t)?'متحقق':'غير متحقق';
 let body=p('نموذج تقرير كمي ووصفي',{size:29,color:'920D39',bold:true,center:true,after:65});
 body+=p(`لتحليل نتائج ${analysis.examName} لمادة ${analysis.subjectLabel} للعام الأكاديمي ${analysis.academicYear}`,{size:21,bold:true,center:true,after:125});
 body+=p(`اسم المدرسة: ${analysis.schoolName}        المعلم: ${analysis.teacher}`,{size:17,bold:true,after:55});
 body+=p(`المنسق الفاضل: ${analysis.coordinator||'................................'}،`,{size:19,after:60});
 body+=p(`بعد قراءة نتائج الطلبة للصفوف التي أقوم بتدريسها في ${analysis.examName} لمادة ${analysis.subjectLabel}، أقدم تقريرًا كميًا ووصفيًا يوضح نسب النجاح والتحصيل الأكاديمي ومستويات الطلبة المختلفة، والتغير بين الاختبارات والتحديات والحلول المقترحة.`,{size:18,after:90});
 // The source template orders the columns from RTL: indicator -> teacher's classes -> total -> achievement of target.
 const metricRows=[
  ['نسبة النجاح في الاختبار','success','percent',targets.success],
  [`نسبة التحصيل الأكاديمي في ${analysis.examName}`,'achievement','percent',targets.achievement],
  [`نسبة التحصيل الأكاديمي في ${analysis.prevExamName||'الاختبار السابق'} (العينة المشتركة)`,'matchedPrevious','percent',null],
  ['القيمة المضافة في التحصيل الأكاديمي بين الاختبارين','valueAdded','change',targets.valueAdded],
  ['نسبة الطلبة الحاصلين على 90% فأعلى','high90','percent',targets.high90]
 ];
 for(let start=0;start<analysis.groups.length;start+=3){
  const chunk=analysis.groups.slice(start,start+3);
  if(start)body+=heading('تابع الشعب الدراسية للمعلم',{size:19});
  const rows=[['الشعب الدراسية / بنود التقرير',...chunk.map(g=>g.className),'إجمالي المستوى','تحقيق المستهدف']];
  const value=(g,m)=>m[2]==='change'?change(g[m[1]]):fmt(g[m[1]]);
  for(const m of metricRows){rows.push([m[0],...chunk.map(g=>value(g,m)),value(analysis,m),m[3]===null?'لا تتوافر مقارنة مستقلة':achieved(analysis[m[1]],m[3])]);}
  if(start+chunk.length>=analysis.groups.length){
   rows.push([{text:'تفسير النتائج (الأسباب / التحديات / الحلول)',bold:true,color:'FFFFFF',shade:'920D39'},{text:edits.interpretation||SR63.teacherReportNarrative(analysis),span:chunk.length+2,size:17}]);
   rows.push([{text:'التغذية الراجعة من المنسق',bold:true,color:'FFFFFF',shade:'920D39'},{text:edits.feedback||'يُرجى مراجعة المؤشرات والإجراءات ونتائج التقويم التشخيصي واعتماد المقترحات المناسبة.',span:chunk.length+2,size:17}]);
  }
  body+=gridTable(rows,[3950,...chunk.map(()=>1250),1750,1750],{size:16,head:true,alternate:false,compact:true});
 }
 body+=p(`ملاحظة: القيمة المضافة تقاس بفارق النسب المئوية للطلاب ذوي نتيجتين فعليتين فقط وعددهم ${analysis.compared} طالبًا. لا يعامل الغياب أو عدم الرصد باعتباره صفرًا.`,{size:15,color:'526B77',after:80});
 if(edits.challenges||edits.solutions){
  body+=heading('التحديات والإجراءات المساندة',{size:20});
  if(edits.challenges)body+=p(edits.challenges,{size:17});
  if(edits.solutions)body+=p(edits.solutions,{size:17});
 }
 body+=heading('اسم المعلم والمنسق وجهة الاعتماد',{size:21});body+=sign;
 return make(body,`التقرير-الكمي-والوصفي-${analysis.teacher}-${analysis.subjectLabel}-${analysis.examName}`);
};
